interface User {
  name: string;
  email: string;
}

async function getUser(): Promise<User> {
  try {
    const res = await fetch('/api/users/profile');
    return res.json();
  } catch {
    // Return mock data for build time
    return { name: 'Default User', email: 'user@example.com' };
  }
}

export default async function UserProfile() {
  const user = await getUser();

  return (
    <div>
      <h2>User Profile</h2>
      <div>{user.name}</div>
      <div>{user.email}</div>
    </div>
  );
}

